    'type_section' => 'html',
    'titre_section' => 'Governance Committees & Personalities',
    'sous_titre' => 'Governance Committees & Personalities',
    'contenu_texte' => '<div class="gov-section"><!-- ===== GOVERNANCE COMMITTEES ===== -->
<h2>Governance Committees &amp; Personalities</h2>
<div class="gov-card-grid"><!-- 2.1 Executive Management Committee -->
<div class="gov-card">
<div class="gov-card-header">
<div class="gov-icon">?</div>
<h4>Executive Management Committee <span class="badge-committee">EMC</span></h4>
</div>
<ul>
<li>Strategic planning &amp; policy approval</li>
<li>Oversees departmental coordination</li>
<li>Budget &amp; investment decisions</li>
</ul>
</div>
<!-- 2.2 Governance & Compliance -->
<div class="gov-card">
<div class="gov-card-header">
<div class="gov-icon">?ï¸</div>
<h4>Governance &amp; Compliance</h4>
</div>
<ul>
<li>Ensures regulatory compliance (ZAMRA, ZEMA, GMP, ISO)</li>
<li>Oversees ethical, legal and risk management frameworks</li>
<li>Monitors internal policies, accountability &amp; transparency</li>
</ul>
</div>
<!-- 2.3 Quality Management Committee -->
<div class="gov-card">
<div class="gov-card-header">
<div class="gov-icon">✅</div>
<h4>Quality Management Committee <span class="badge-committee">QMC</span></h4>
</div>
<ul>
<li>Ensures GMP/ISO compliance</li>
<li>Reviews internal audits, CAPA, deviations</li>
<li>Approves changes to SOPs/QA systems</li>
</ul>
</div>
<!-- 2.4 Ethics & Compliance Committee -->
<div class="gov-card">
<div class="gov-card-header">
<div class="gov-icon">⚖️</div>
<h4>Ethics &amp; Compliance Committee</h4>
</div>
<ul>
<li>Monitors regulatory, legal, environmental compliance</li>
<li>Prevents conflicts of interest</li>
<li>Promotes ethical business conduct</li>
</ul>
</div>
<!-- 2.5 Product Development/R&D Committee -->
<div class="gov-card">
<div class="gov-card-header">
<div class="gov-icon">?</div>
<h4>Product Development / R&amp;D Committee</h4>
</div>
<ul>
<li>Approves new formulations</li>
<li>Oversees clinical validation</li>
<li>Guides innovation strategy</li>
</ul>
</div>
<!-- 2.6 Health & Safety Committee -->
<div class="gov-card">
<div class="gov-card-header">
<div class="gov-icon">?</div>
<h4>Health &amp; Safety Committee</h4>
</div>
<ul>
<li>Implements occupational health/safety policies</li>
<li>Risk assessment &amp; emergency preparedness</li>
<li>Coordinates safety training</li>
</ul>
</div>
</div>
<!-- ===== DEPARTMENTS & RESPONSIBILITIES ===== -->
<h2>Departments &amp; Responsibilities</h2>
<div class="gov-card-grid"><!-- 3.1 Production Department -->
<div class="gov-card">
<div class="gov-card-header">
<div class="gov-icon">?</div>
<h4>Production Department</h4>
</div>
<ul>
<li>Executes manufacturing (extraction, formulation, packaging)</li>
<li>Maintains batch records, GMP hygiene</li>
<li>Manages equipment operations</li>
</ul>
</div>
<!-- 3.2 Quality Assurance -->
<div class="gov-card">
<div class="gov-card-header">
<div class="gov-icon">?</div>
<h4>Quality Assurance (QA)</h4>
</div>
<ul>
<li>GMP implementation &amp; document control (SOPs, CAPA)</li>
<li>In-process and post-production checks</li>
<li>Batch release authorization</li>
</ul>
</div>
<!-- 3.3 Quality Control -->
<div class="gov-card">
<div class="gov-card-header">
<div class="gov-icon">?</div>
<h4>Quality Control (QC)</h4>
</div>
<ul>
<li>Lab testing (raw materials, in-process, finished products)</li>
<li>Microbiology, chemical, and instrumental testing</li>
<li>Stability testing and sampling</li>
</ul>
</div>
<!-- 3.4 Research & Development -->
<div class="gov-card">
<div class="gov-card-header">
<div class="gov-icon">?</div>
<h4>Research &amp; Development (R&amp;D)</h4>
</div>
<ul>
<li>Product formulation &amp; standardization</li>
<li>Pilot production and validation</li>
<li>Ingredient functionality research</li>
</ul>
</div>
<!-- 3.5 Regulatory Affairs -->
<div class="gov-card">
<div class="gov-card-header">
<div class="gov-icon">?</div>
<h4>Regulatory Affairs</h4>
</div>
<ul>
<li>Handles product registration (ZAMRA, MOH)</li>
<li>Prepares dossiers, compliance documentation</li>
<li>Communicates with relevant authorities</li>
</ul>
</div>
<!-- 3.6 Supply Chain & Logistics -->
<div class="gov-card">
<div class="gov-card-header">
<div class="gov-icon">?</div>
<h4>Supply Chain &amp; Logistics</h4>
</div>
<ul>
<li>Procurement of raw materials, capsules, packaging</li>
<li>Warehouse &amp; stock management</li>
<li>Delivery/distribution planning</li>
</ul>
</div>
<!-- 3.8 Finance & Accounting -->
<div class="gov-card">
<div class="gov-card-header">
<div class="gov-icon">?</div>
<h4>Finance &amp; Accounting</h4>
</div>
<ul>
<li>Manages budgeting, salaries, audits</li>
<li>Prepares financial statements</li>
<li>Handles L/Cs, T/Ts, and bank relations</li>
</ul>
</div>
<!-- 3.9 Marketing and Sales -->
<div class="gov-card">
<div class="gov-card-header">
<div class="gov-icon">?</div>
<h4>Marketing and Sales</h4>
</div>
<ul>
<li>Develops branding &amp; promotion strategy</li>
<li>Manages media, partnerships, and advertising</li>
<li>Supports product launch</li>
</ul>
</div>
<!-- 3.10 Human Resources -->
<div class="gov-card">
<div class="gov-card-header">
<div class="gov-icon">?</div>
<h4>Human Resources (HR)</h4>
</div>
<ul>
<li>Staff recruitment, onboarding, and training</li>
<li>Oversees compliance with labor</li>
<li>Evaluates performance &amp; HR policies</li>
</ul>
</div>
<!-- 3.11 Facility Engineering & Maintenance -->
<div class="gov-card">
<div class="gov-card-header">
<div class="gov-icon">?</div>
<h4>Facility Engineering &amp; Maintenance</h4>
</div>
<ul>
<li>Maintains cleanroom, HVAC, utilities</li>
<li>Ensures GMP-compliant infrastructure</li>
<li>Coordinates equipment calibration/repairs</li>
</ul>
</div>
<!-- 3.12 Risk Management -->
<div class="gov-card">
<div class="gov-card-header">
<div class="gov-icon">⚠️</div>
<h4>Risk Management</h4>
</div>
<ul>
<li>Identifies, assesses, and monitors risks</li>
<li>Develops mitigation strategies and contingency plans</li>
<li>Integrates risk controls into operations and planning</li>
</ul>
</div>
<!-- 3.13 IT & Data Systems -->
<div class="gov-card">
<div class="gov-card-header">
<div class="gov-icon">?</div>
<h4>IT &amp; Data Systems</h4>
</div>
<ul>
<li>Manages data integrity, cyber security, LIMS/ERP</li>
<li>Supports automation and traceability</li>
<li>Digital compliance (e.g., 21 CFR Part 11)</li>
</ul>
</div>
</div>
<!-- ===== LICENSING AND REGULATORY COMPLIANCE ===== -->
<h2>Licensing and Regulatory Compliance</h2>
<div class="license-tag-list"><span class="license-tag">PACRA &ndash; Business Registration</span> <span class="license-tag">ZDA &ndash; Investment Licence</span> <span class="license-tag">ZEMA &ndash; EIA Certificate</span> <span class="license-tag">ZEMA &ndash; Screening EPB Report</span> <span class="license-tag">ZEMA &ndash; Waste Management Licence</span> <span class="license-tag">ZMRA &ndash; Site Approval Certificate</span> <span class="license-tag">ZMRA &ndash; Product Registration</span> <span class="license-tag">ZAMRA &ndash; GMP Inspection</span> <span class="license-tag">ZAMRA &ndash; Manufacturing Licence</span> <span class="license-tag">IMMIGRATION &ndash; Investor Permit</span> <span class="license-tag">ZABS &ndash; Product Testing &amp; Application</span> <span class="license-tag">ZABS &ndash; Factory Inspection</span> <span class="license-tag">ZABS &ndash; Certification Mark</span> <span class="license-tag">Health Dept &ndash; Premises Hygiene Clearance</span> <span class="license-tag">Health Dept &ndash; Food Safety Inspection</span> <span class="license-tag">Health Dept &ndash; Food Handling Certificate</span> <span class="license-tag">Health Dept &ndash; Occupational Health Risk Assessment</span> <span class="license-tag">Health Dept &ndash; Annual Health Compliance</span> <span class="license-tag">Land Title Deeds (Headmen, Chief, Ministry)</span> <span class="license-tag">ISO 9001 &ndash; QMS Initial Certification</span> <span class="license-tag">ISO 9001 &ndash; Annual Surveillance</span> <span class="license-tag">ISO 22000 &ndash; Food Safety</span> <span class="license-tag">ISO 14001 &ndash; Environmental Governance (Initial)</span> <span class="license-tag">ISO 14001 &ndash; Annual Surveillance</span> <span class="license-tag">ISO 45001 &ndash; OH&amp;S (Initial)</span> <span class="license-tag">ISO 45001 &ndash; Annual Surveillance</span> <span class="license-tag">ISO 14644 &ndash; Cleanroom Qualification (ISO 5)</span> <span class="licens