if (!function_exists('_static_section_matches')) {

    function _static_section_matches($sec, $where)
    {
        if (empty($where)) {
            return true;
        }

        foreach ($where as $key => $value) {
            $col = $key;
            $op = '=';

            if (strpos($key, ' !=') !== false) {
                $col = trim(str_replace(' !=', '', $key));
                $op = '!=';
            } elseif (strpos($key, ' >=') !== false) {
                $col = trim(str_replace(' >=', '', $key));
                $op = '>=';
            } elseif (strpos($key, ' <=') !== false) {
                $col = trim(str_replace(' <=', '', $key));
                $op = '<=';
            }

            $secVal = $sec[$col] ?? null;

            if (is_array($value)) {
                if (!in_array($secVal, $value)) {
                    return false;
                }
                continue;
            }

            switch ($op) {
                case '!=':
                    if ($secVal == $value) return false;
                    break;
                case '>=':
                    if (!($secVal >= $value)) return false;
                    break;
                case '<=':
                    if (!($secVal <= $value)) return false;
                    break;
                default:
                    if ($secVal != $value) return false;
            }
        }

        return true;
    }
}

if (!function_exists('static_sections_where')) {

    /**
     * Équivalent statique de Model::read('sections_contenu', ...)
     */
    function static_sections_where($where = [], $order_by = null, $order = 'ASC')
    {
        $out = [];

        foreach (static_sections_all() as $sec) {
            if (_static_section_matches($sec, $where)) {
                $out[] = $sec;
            }
        }

        if ($order_by !== null) {
            usort($out, function ($a, $b) use ($order_by, $order) {
                $va = $a[$order_by] ?? null;
                $vb = $b[$order_by] ?? null;
                if ($va === $vb) return 0;
                $cmp = ($va < $vb) ? -1 : 1;
                return ($order === 'DESC') ? -$cmp : $cmp;
            });
        }

        return $out;
    }
}

if (!function_exists('static_sections_one')) {

    /**
     * Équivalent statique de Model::readOne/read_one('sections_contenu', ...)
     */
    function static_sections_one($where = [])
    {
        foreach (static_sections_all() as $sec) {
            if (_static_section_matches($sec, $where)) {
                return $sec;
            }
        }

        return null;
    }
}

if (!function_exists('static_sections_count')) {

    function static_sections_count($where = [])
    {
        $count = 0;

        foreach (static_sections_all() as $sec) {
            if (_static_section_matches($sec, $where)) {
                $count++;
            }
        }

        return $count;
    }
}
